<QuizCard className="q-card" data-answer="B" answer="B" multi={1}>{"\n                    "}<div className="q-card-header">{"\n                        "}<h3 id="問題-7domain-5" data-qnum="Q7" tabIndex={-1}>{"問題 7(Domain 5)"}</h3>{"\n                        "}<div className="q-badges">{"\n                            "}<span className="q-domain-pill">{"Domain 5: データ保護"}</span>{"\n                            "}<span className="q-mode-pill">{"単一選択"}</span>{"\n                            "}<span className="q-status-pill correct">{"✓ 正解"}</span>{"\n                            "}<span className="q-status-pill wrong">{"✕ 不正解"}</span>{"\n                        "}</div>{"\n                    "}</div>{"\n                    "}<p className="q-stem">{"\n                        お客様が生成した鍵マテリアルを KMS\n                        にインポートして使っている。この鍵について"}<strong >{"正しい"}</strong>{"記述はどれか。\n                    "}</p>{"\n                    "}<ul className="q-options">{"\n                        "}<QuizOption data-opt="A" value="A">{"\n                            "}<span className="q-opt-key">{"A."}</span><span className="q-opt-body">{"自動ローテーションを有効化できる"}</span>{"\n                        "}</QuizOption>{"\n                        "}<QuizOption data-opt="B" value="B">{"\n                            "}<span className="q-opt-key">{"B."}</span><span className="q-opt-body">{"鍵マテリアルに有効期限を設定できる"}</span>{"\n                        "}</QuizOption>{"\n                        "}<QuizOption data-opt="C" value="C">{"\n                            "}<span className="q-opt-key">{"C."}</span><span className="q-opt-body">{"お客様は元の鍵マテリアルを保持する必要がない"}</span>{"\n                        "}</QuizOption>{"\n                        "}<QuizOption data-opt="D" value="D">{"\n                            "}<span className="q-opt-key">{"D."}</span><span className="q-opt-body">{"外部の HSM でのみ暗号操作が行われる"}</span>{"\n                        "}</QuizOption>{"\n                    "}</ul>{"\n                    "}<QuizDetails >{"\n                        "}<summary >{"答えと解説"}</summary>{"\n                        "}<p >{"\n                            "}<strong >{"B"}</strong>{"。インポート鍵は"}<strong >{"自動ローテーション非対応"}</strong>{"で、"}<strong >{"有効期限の設定が可能"}</strong>{"です。お客様はコピーを保持する責任があり、暗号操作は\n                            KMS 内で行われます(外部で行うのは XKS)。\n                        "}</p>{"\n                    "}</QuizDetails>{"\n                "}</QuizCard>
{"\n\n                "}
<QuizCard className="q-card" data-answer="B" answer="B" multi={1}>{"\n                    "}<div className="q-card-header">{"\n                        "}<h3 id="問題-8domain-6" data-qnum="Q8" tabIndex={-1}>{"問題 8(Domain 6)"}</h3>{"\n                        "}<div className="q-badges">{"\n                            "}<span className="q-domain-pill">{"Domain 6: ガバナンス"}</span>{"\n                            "}<span className="q-mode-pill">{"単一選択"}</span>{"\n                            "}<span className="q-status-pill correct">{"✓ 正解"}</span>{"\n                            "}<span className="q-status-pill wrong">{"✕ 不正解"}</span>{"\n                        "}</div>{"\n                    "}</div>{"\n                    "}<p className="q-stem">{"\n                        組織全体で、"}<strong >{"今後 AWS の API が変わっても"}</strong>{"EC2 の IMDSv2\n                        を既定で必須とする構成を維持したい。最も適切なのはどれか。\n                    "}</p>{"\n                    "}<ul className="q-options">{"\n                        "}<QuizOption data-opt="A" value="A">{"\n                            "}<span className="q-opt-key">{"A."}</span><span className="q-opt-body">{"各アカウントに Config ルールを配布する"}</span>{"\n                        "}</QuizOption>{"\n                        "}<QuizOption data-opt="B" value="B">{"\n                            "}<span className="q-opt-key">{"B."}</span><span className="q-opt-body">{"宣言型ポリシー(Declarative policies)を適用する"}</span>{"\n                        "}</QuizOption>{"\n                        "}<QuizOption data-opt="C" value="C">{"\n                            "}<span className="q-opt-key">{"C."}</span><span className="q-opt-body">{"各インスタンスで手動設定する"}</span>{"\n                        "}</QuizOption>{"\n                        "}<QuizOption data-opt="D" value="D">{"\n                            "}<span className="q-opt-key">{"D."}</span><span className="q-opt-body">{"タグポリシーを設定する"}</span>{"\n                        "}</QuizOption>{"\n                    "}</ul>{"\n                    "}<QuizDetails >{"\n                        "}<summary >{"答えと解説"}</summary>{"\n                        "}<p >{"\n                            "}<strong >{"B"}</strong>{"。宣言型ポリシーは、サービスの"}<strong >{"基準構成を組織全体で強制"}</strong>{"します。Config\n                            は検知中心で、タグポリシーはタグの標準化用です。\n                        "}</p>{"\n                    "}</QuizDetails>{"\n                "}</QuizCard>
